    "blurDataURL": "data:image/webp;base64,UklGRmAAAABXRUJQVlA4IFQAAABwAwCdASoQABYAPu1kq04ppaQiMAgBMB2JQAALeivY0OQkaEAA/vQotpNLOYPGWBcIPFCGoZSH3w1vu67Atwz8yzLNuhylq3mmxsRyqrWm7iQAAAA="
